        if cur:
            repaired.append(cur)
            repaired_loads.append(cur_load)
    routes = repaired
    loads = repaired_loads

    # Local search: route-internal ordering to reduce travel.
    def route_length(route):
        if not route:
            return 0.0
        if depot_xy is None or not coord:
            return float(len(route))
        total = 0.0
        prev = depot_xy
        for cid in route:
            if cid in coord:
                cur = coord[cid]
                total += dist2(prev, cur)
                prev = cur
        total += dist2(prev, depot_xy)
        return total

    def nearest_neighbor_order(route):
        if depot_xy is None or not coord:
            return route[:]
        remaining = route[:]
        out = []
        cur = depot_xy
        while remaining:
            best_i = 0
            best_d = None
            for i, cid in enumerate(remaining):
                if cid in coord:
                    d = dist2(cur, coord[cid])
                else:
                    d = 0
                if best_d is None or d < best_d or (d == best_d and cid < remaining[best_i]):
                    best_d = d
                    best_i = i
            cid = remaining.pop(best_i)
            out.append(cid)
            if cid in coord:
                cur = coord[cid]
        return out

    routes = [nearest_neighbor_order(r) for r in routes]

    # Simple relocate improvement between routes: move single customers to better fit loads if possible.
    changed = True
    while changed:
        changed = False
        for i in range(len(routes)):
            for j in range(len(routes)):
                if i == j:
                    continue
                ri = routes[i]
                rj = routes[j]
                li = sum(demand.get(c, 0) for c in ri)
                lj = sum(demand.get(c, 0) for c in rj)
                for idx, cid in enumerate(ri):
                    d = demand.get(cid, 0)
                    if lj + d <= capacity:
                        # deterministic acceptance if route count can be reduced or lengths improve
                        new_ri = ri[:idx] + ri[idx + 1 :]
                        new_rj = rj + [cid]
                        if not new_ri:
                            # Prefer removing empty route
                            routes[i] = new_rj
                            routes[j] = []
                            changed = True
                            break
                        old_cost = route_length(ri) + route_length(rj)
                        new_cost = route_length(new_ri) + route_length(new_rj)
                        if new_cost <= old_cost:
                            routes[i] = new_ri
                            routes[j] = new_rj
                            changed = True
                            break
                if changed:
                    break
            if changed:
                break
        routes = [r for r in routes if r]

    # Final sanity: ensure every customer exactly once, no depot.
    seen = {}
    final_routes = []
    for r in routes:
        nr = []
        load = 0
        for cid in r:
            if cid == depot:
                continue
            if seen.get(cid, 0) == 0:
                nr.append(cid)
                seen[cid] = 1
                load += demand.get(cid, 0)
        if nr:
            final_routes.append(nr)

    missing = [cid for cid in ids if seen.get(cid, 0) == 0]
    if missing:
        # Insert missing customers using best-fit deterministic policy.
        for cid in missing:
            d = demand.get(cid, 0)
            best = -1
            best_slack = None
            for ridx, r in enumerate(final_routes):
                load = sum(demand.get(c, 0) for c in r)
                slack = capacity - load
                if d <= slack:
                    if best_slack is None or slack - d < best_slack or (slack - d == best_slack and ridx < best):
                        best_slack = slack - d
                        best = ridx
            if best >= 0:
                final_routes[best].append(cid)
            else:
                final_routes.append([cid])

    # Ensure capacity feasibility with a final split if needed.
    feasible = []
    for r in final_routes:
        cur = []
        cur_load = 0
        for cid in r:
            d = demand.get(cid, 0)
            if cur and cur_load + d > capacity:
                feasible.append(cur)
                cur = [cid]
                cur_load = d
            else:
                cur.append(cid)
                cur_load += d
        if cur:
            feasible.append(cur)

    return feasible
